"""
MoE probe: Discover which env vars fused_moe actually reads.
Prints to stderr so it's visible in submission output.
"""

import sys
import os
import inspect
import torch
from task import input_t, output_t
from aiter import ActivationType, QuantType
from aiter.fused_moe import fused_moe

os.environ["AITER_USE_NT"] = "1"
os.environ["AITER_USE_OPUS_MOE_SORTING"] = "1"

# Probe: inspect fused_moe source for env var references
try:
    src = inspect.getsource(fused_moe)
    print("=== fused_moe SOURCE ENV VARS ===", file=sys.stderr)
    for line_num, line in enumerate(src.split("\n"), 1):
        low = line.lower()
        if "environ" in low or "os.getenv" in low or "AITER_" in line:
            print(f"  L{line_num}: {line.rstrip()}", file=sys.stderr)
    print("=== END fused_moe SOURCE ===", file=sys.stderr)
except Exception as e:
    print(f"fused_moe source error: {e}", file=sys.stderr)

# Probe: inspect the module tree for env var references
try:
    import aiter.fused_moe as fm_mod
    for name in dir(fm_mod):
        obj = getattr(fm_mod, name)
        if callable(obj) and not name.startswith("_"):
            try:
                s = inspect.getsource(obj)
                matches = [l.strip() for l in s.split("\n") if "AITER_" in l or "environ" in l.lower()]
                if matches:
                    print(f"=== {name} ENV REFS ===", file=sys.stderr)
                    for m in matches[:10]:
                        print(f"  {m}", file=sys.stderr)
            except Exception:
                pass
except Exception as e:
    print(f"module probe error: {e}", file=sys.stderr)

# Probe: check aiter.jit and aiter.ops for env var usage
for mod_name in ["aiter.jit", "aiter.ops", "aiter.ops.triton"]:
    try:
        mod = __import__(mod_name, fromlist=[""])
        for name in dir(mod):
            if "AITER" in name.upper() or "config" in name.lower():
                print(f"{mod_name}.{name} = {getattr(mod, name, 'N/A')}", file=sys.stderr)
    except Exception:
        pass

# Probe: check fused_moe signature
try:
    sig = inspect.signature(fused_moe)
    print(f"\n=== fused_moe SIGNATURE ===", file=sys.stderr)
    print(f"  {sig}", file=sys.stderr)
except Exception as e:
    print(f"sig error: {e}", file=sys.stderr)

# Probe: search for specific env var names in all reachable sources
ENV_VARS = [
    "AITER_BLOCK_N", "AITER_BLOCK_K", "AITER_WAVES_PER_EU",
    "AITER_NUM_WARPS", "AITER_NUM_STAGES", "AITER_OCCUPANCY",
    "AITER_USE_PERSISTENT", "AITER_STREAMK", "AITER_MOE_PADDING",
    "AITER_KSPLIT", "AITER_BLOCK_M", "AITER_BYPASS_TUNE_CONFIG",
    "AITER_USE_NT", "AITER_USE_OPUS_MOE_SORTING",
]

try:
    import aiter
    aiter_path = os.path.dirname(aiter.__file__)
    print(f"\n=== SCANNING {aiter_path} for env vars ===", file=sys.stderr)
    found = {}
    for root, dirs, files in os.walk(aiter_path):
        for fname in files:
            if fname.endswith(".py"):
                fpath = os.path.join(root, fname)
                try:
                    with open(fpath) as f:
                        content = f.read()
                    for ev in ENV_VARS:
                        if ev in content:
                            rel = os.path.relpath(fpath, aiter_path)
                            if ev not in found:
                                found[ev] = []
                            found[ev].append(rel)
                except Exception:
                    pass
    for ev in ENV_VARS:
        files = found.get(ev, [])
        status = ", ".join(files) if files else "NOT FOUND"
        print(f"  {ev}: {status}", file=sys.stderr)
    print("=== END SCAN ===", file=sys.stderr)
except Exception as e:
    print(f"scan error: {e}", file=sys.stderr)


_state: dict = {"ksplit": None, "block_m": None}


def custom_kernel(data: input_t) -> output_t:
    (
        hidden_states, gate_up_weight, down_weight,
        gate_up_weight_scale, down_weight_scale,
        gate_up_weight_shuffled, down_weight_shuffled,
        gate_up_weight_scale_shuffled, down_weight_scale_shuffled,
        topk_weights, topk_ids, config,
    ) = data

    hidden_pad = config["d_hidden_pad"] - config["d_hidden"]
    intermediate_pad = config["d_expert_pad"] - config["d_expert"]

    num_experts = gate_up_weight_shuffled.shape[0]
    estimated_m = topk_ids.numel() // num_experts

    if estimated_m >= 80:
        ks = "default"
        bm = None
    elif estimated_m >= 25:
        ks = "2"
        bm = None
    elif estimated_m >= 8:
        ks = "2"
        bm = "64"
    else:
        ks = "2"
        bm = "64"

    if _state["ksplit"] != ks or _state["block_m"] != bm:
        if ks == "default":
            os.environ.pop("AITER_BYPASS_TUNE_CONFIG", None)
            os.environ.pop("AITER_KSPLIT", None)
            os.environ.pop("AITER_BLOCK_M", None)
        else:
            os.environ["AITER_BYPASS_TUNE_CONFIG"] = "1"
            os.environ["AITER_KSPLIT"] = ks
            if bm:
                os.environ["AITER_BLOCK_M"] = bm
            else:
                os.environ.pop("AITER_BLOCK_M", None)
        _state["ksplit"] = ks
        _state["block_m"] = bm

    return fused_moe(
        hidden_states, gate_up_weight_shuffled, down_weight_shuffled,
        topk_weights, topk_ids, expert_mask=None,
        activation=ActivationType.Silu, quant_type=QuantType.per_1x32,
        doweight_stage1=False,
        w1_scale=gate_up_weight_scale_shuffled,
        w2_scale=down_weight_scale_shuffled,
        a1_scale=None, a2_scale=None,
        hidden_pad=hidden_pad, intermediate_pad=intermediate_pad,
    )

