                s = inspect.getsource(obj)
                matches = [l.strip() for l in s.split("\n") if "AITER_" in l or "environ" in l.lower()]
                if matches:
                    print(f"=== {name} ENV REFS ===", file=sys.stderr)
                    for m in matches[:10]:
